    def set_item_key(self):
        self.comboBox.addItems([str(item) for item in self.total_key])

    def split_key(self):
        valid_key = self.comboBox.currentText()
        self.valid_key = ast.literal_eval(valid_key)
        for key, val in self.built_in_objs.items():
            if self.valid_key[0] in key:
                self.valid_values = val
        self.pyuic = self.valid_values['pyuic'][self.valid_key]
        self.model_loader = self.valid_values['model_loader'][self.valid_key]

    def broswer_folder(self): 
        folder = QFileDialog.getExistingDirectory(
            None,
            "Select Folder",
            "",
            QFileDialog.ShowDirsOnly | QFileDialog.DontResolveSymlinks
        )
        if folder:
            self.lineEdit.setText(folder)

    def generate_table(self):
        path = self.lineEdit.text().strip()
        list_obj = glob.glob(os.path.join(path, '*.jpg'))

        self.tableWidget.setRowCount(len(list_obj))
        for row, file_path in enumerate(list_obj):
            shot_item = QTableWidgetItem(file_path)
            self.tableWidget.setItem(row, 0, shot_item)
            detect_button = QtWidgets.QPushButton("Detect")
            detect_button.clicked.connect(partial(self.on_detect_clicked, file_path))
            self.tableWidget.setCellWidget(row, 1, detect_button)
            view_button = QtWidgets.QPushButton("View")
            view_button.clicked.connect(partial(self.on_view_clicked, file_path))
            self.tableWidget.setCellWidget(row, 2, view_button)
            export_button = QtWidgets.QPushButton("(*.csv/xlsx)")
            export_button.clicked.connect(partial(self.on_export_clicked, file_path))
            self.tableWidget.setCellWidget(row, 3, export_button)

    def on_detect_clicked(self, file_path):
        result_image_rgb = cv2.imread(file_path)
        if result_image_rgb is None:
            _log.error("Lỗi đọc ảnh: %s", file_path)
            return
        
        self.target_width = self.label_display_image.width()
        self.target_height = self.label_display_image.height()

        if not self.list_size:
            self.list_size.append(self.target_width)
            self.list_size.append(self.target_height)

        result_image_rgb, flag, list_register = self.processer.process_image_func(
                result_image_rgb, self.model_loader, self.pyuic, True, self.valid_key, 12,
                mode_load_jumper=False,
            )
        self.dict_view_results[file_path] = list_register

        result_text = f'RESULT: {"OK" if flag else "NG"}'
        color = (0, 255, 0) if flag else (0, 0, 255)
        cv2.putText(result_image_rgb, result_text, (10, 50),
                    cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 1)
        h, w = result_image_rgb.shape[:2]
        qimg = QtGui.QImage(result_image_rgb.data, w, h,
                            result_image_rgb.strides[0],
                            QtGui.QImage.Format_RGB888)
        pix = QtGui.QPixmap.fromImage(qimg)

        if self.list_size:
            pix = pix.scaled(self.list_size[0], self.list_size[1],
                         QtCore.Qt.KeepAspectRatio,
                         QtCore.Qt.SmoothTransformation)
        else:
            pix = pix.scaled(self.target_width, self.target_height,
                         QtCore.Qt.KeepAspectRatio,
                         QtCore.Qt.SmoothTransformation)
        QtCore.QMetaObject.invokeMethod(
            self.label_display_image, "setPixmap",
            QtCore.Qt.QueuedConnection,
            QtCore.Q_ARG(QtGui.QPixmap, pix)
        )

    def on_view_clicked(self, file_path):
        result = next(
            ((key, vals) for key, vals in self.dict_view_results.items() if file_path in key), 
            None
        )
        if result:
            key, vals = result
            show_data_viewer(vals, key)
        else:
            QMessageBox.information(None, "Lưu ý", "Hãy Detect trước khi xem kết quả")

    def on_export_clicked(self, file_path):
        _log.info("[EXPORT] %s", file_path)

